import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Literature reviews","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reviews.md","filePath":"guide/reviews.md","lastUpdated":1793111003000}'),o={name:"guide/reviews.md"};function n(i,e,d,h,c,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="literature-reviews" tabindex="-1">Literature reviews <a class="header-anchor" href="#literature-reviews" aria-label="Permalink to &quot;Literature reviews&quot;">​</a></h1><p><strong>Experimental.</strong> Turn selected abstract evidence into a thematic outline and an editable draft with citations.</p><p>The feature uses available papers and abstracts, not automatically read full-text PDFs. Check the draft against original research.</p><h2 id="module-and-evidence" tabindex="-1">Module and evidence <a class="header-anchor" href="#module-and-evidence" aria-label="Permalink to &quot;Module and evidence&quot;">​</a></h2><p>Review contains Papers, Outline, Draft, and Citation evidence. Expand the model controls within the review page to configure its model; it cannot change during generation. Its sidebar lists reviews only. Citation evidence brings together paragraph citations and paper relations. New reviews preserve available source-map snapshots; older reviews may still depend on the source search.</p><h2 id="_1-choose-a-search" tabindex="-1">1. Choose a search <a class="header-anchor" href="#_1-choose-a-search" aria-label="Permalink to &quot;1. Choose a search&quot;">​</a></h2><p>Start from selected results, or choose <strong>Reviews → New review</strong> and an existing search.</p><p>Online reviews require login and a saved source search; Community stores them locally.</p><h2 id="_2-set-the-scope" tabindex="-1">2. Set the scope <a class="header-anchor" href="#_2-set-the-scope" aria-label="Permalink to &quot;2. Set the scope&quot;">​</a></h2><p>Provide a topic and select English or Chinese, a writing model, and Short, Standard, or Detailed.</p><p>Default chapter counts are <strong>1, 3, and 6</strong>, with a custom range of <strong>1–14</strong>. This is not a fixed word-count guarantee; the evidence and outline determine what can be written.</p><p>Open <strong>More options</strong> to choose the paragraph count per chapter and the target paragraph length. Automatic paragraph counts follow the selected scope; custom counts allow <strong>1–10 paragraphs per chapter</strong>. For Chinese output, custom length is <strong>100–1,500 characters</strong> per paragraph; for English, <strong>50–800 words</strong>. These are writing targets, so check the generated outline and draft.</p><p>Configure a writing model in Community or with your own key online, or choose an allowed model in PaperSeek Service.</p><h2 id="_3-select-papers" tabindex="-1">3. Select papers <a class="header-anchor" href="#_3-select-papers" aria-label="Permalink to &quot;3. Select papers&quot;">​</a></h2><p>The length sets a suggested number of papers: about <strong>8–20</strong> for Short, <strong>20–45</strong> for Standard, and <strong>40–80</strong> for Detailed. Custom chapters or paragraphs are estimated from the paragraph count. Manual selection can use the whole search, up to <strong>256 papers</strong>; this is a limit, not a target.</p><p>Tick papers yourself, or choose <strong>Auto-select by topic</strong>: the writing model considers the first <strong>256 papers with usable abstracts in search-rank order</strong>, picks papers that cover distinct themes, methods, and study populations, and gives a reason for each. You can still add or remove papers, including manually adding papers ranked beyond that range. Auto-select does not count as a writing task and uses no credits with PaperSeek Service.</p><p>Each paper shows its CCF class, CAS tier and JCR quartile, and its conference acceptance, when the search labelled them. <strong>Journal</strong> next to the search box narrows the list to a tier or class; <strong>Select all with abstracts</strong> then selects only the papers listed.</p><p>Only papers with abstracts can be selected. More papers do not automatically mean better evidence. Records without meaningful research content may not contribute to the draft.</p><p>You can switch modules while auto-selection runs. Return to Reviews and open the <strong>Selecting / Ready to confirm</strong> draft in the sidebar to recover the settings, selected papers, and reasons. This tab keeps one pending draft; refreshing, closing the page, or signing out clears it. <strong>Stop waiting</strong> ignores any later selection result but may not stop computation already running at the model provider. <strong>Discard draft</strong> clears the draft.</p><h2 id="_4-check-the-outline" tabindex="-1">4. Check the outline <a class="header-anchor" href="#_4-check-the-outline" aria-label="Permalink to &quot;4. Check the outline&quot;">​</a></h2><p>Review the themes, chapter structure, paragraph plans, and assigned papers. Look for omitted perspectives and a scope broader than the evidence supports.</p><p>Each generated paragraph plan has at most <strong>10 papers</strong>. Papers the outline does not use are listed under <strong>Papers left out of the outline</strong>, each with a reason. To bring one back, add it to a chapter&#39;s supporting papers; it then leaves the excluded list. A paper you remove from every chapter is recorded as removed by you.</p><p>Use <strong>Save outline</strong> to save edits without starting a writing task. Use <strong>Confirm outline and write</strong> or <strong>Save outline and write</strong> when ready to generate the draft. Leaving with unsaved edits prompts you to keep editing or discard them.</p><h2 id="_5-read-and-revise" tabindex="-1">5. Read and revise <a class="header-anchor" href="#_5-read-and-revise" aria-label="Permalink to &quot;5. Read and revise&quot;">​</a></h2><p>Edit text, rewrite an individual section, and inspect available versions. A changed outline does not automatically make the old draft match it; check the current version and task state.</p><p>Choose numbered or Harvard author–year citation display. Exports follow that choice.</p><p>While writing, the model may leave out a planned paper if it gives a reason, for example that the paper does not address the paragraph&#39;s comparison or repeats another study. <strong>Planned papers not cited</strong> at the end of each chapter lists these papers and reasons. When the evidence check finds a reason doubtful, it is marked with an explanation.</p><p>If an omission reason could not be checked, the draft is kept and that reason is marked as unchecked for manual review. An unfinished check does not mean the reason was accepted.</p><p>Papers a paragraph cites without placing them beside a specific claim are listed under the paragraph as <strong>Also cited, not placed beside a claim</strong>. Exports keep this line.</p><p>Evidence checks can flag missing or inconsistent support. They do not certify scientific truth. Read cited papers before relying on the claims.</p><p>Evidence quotations retain the source abstract&#39;s wording and language, even when the draft uses another language. A quotation may be longer when a shorter supporting passage cannot be reliably identified. Check that it supports the stated observation; text that cannot be verified against the abstract is not usable evidence.</p><h2 id="_6-export" tabindex="-1">6. Export <a class="header-anchor" href="#_6-export" aria-label="Permalink to &quot;6. Export&quot;">​</a></h2><ul><li><strong>Markdown</strong> for further editing.</li><li><strong>Word (.docx)</strong> for document workflows.</li><li><strong>BibTeX</strong> for the references.</li></ul><h2 id="if-generation-stops" tabindex="-1">If generation stops <a class="header-anchor" href="#if-generation-stops" aria-label="Permalink to &quot;If generation stops&quot;">​</a></h2><p>Inspect the current or latest task separately from the saved draft. A stopped task does not erase the outline or completed chapters. Model access, credit, timeouts, and structured-response errors can interrupt an outline or section. Fix the cause and retry the affected operation instead of creating duplicate reviews.</p><p>Refreshing reconnects to saved state; it does not restart generation. Online writing shares the <a href="./../online/#when-your-task-is-queued">execution queue</a> with searches.</p>',36)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
